"use strict";(globalThis.webpackChunkshellui_docs=globalThis.webpackChunkshellui_docs||[]).push([[7492],{31(e){e.exports=JSON.parse('{"version":{"pluginId":"identity","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/identity/","label":"Introduction","docId":"index","unlisted":false},{"type":"link","href":"/identity/oauth-login","label":"OAuth","docId":"oauth-login","unlisted":false},{"type":"link","href":"/identity/magic-link","label":"Magic link","docId":"magic-link","unlisted":false},{"type":"link","href":"/identity/oauth-providers","label":"OAuth providers","docId":"oauth-providers","unlisted":false},{"type":"link","href":"/identity/scim","label":"SCIM","docId":"scim","unlisted":false},{"type":"link","href":"/identity/actions","label":"Action triggers","docId":"actions","unlisted":false},{"type":"link","href":"/identity/configuration","label":"Configuration","docId":"configuration","unlisted":false},{"type":"link","href":"/identity/company-access","label":"Company access","docId":"company-access","unlisted":false},{"type":"link","href":"/identity/jwks","label":"JWKS","docId":"jwks","unlisted":false},{"type":"link","href":"/identity/security-hardening","label":"Security","docId":"security-hardening","unlisted":false},{"type":"link","href":"/identity/metrics","label":"Metrics","docId":"metrics","unlisted":false},{"type":"link","href":"/identity/RELEASES","label":"Releases","docId":"RELEASES","unlisted":false}]},"docs":{"actions":{"id":"actions","title":"Action triggers (domain events \u2192 webhooks)","description":"Company owners (and Django staff) can react when identity events happen (SCIM access changes, account create/delete, group changes, SCIM conflicts, token lifecycle) using webhook Action rules in the Shellui admin API or Django admin. Each rule maps a catalog event type (for example identity.scim.user.provisioned) to an HTTPS webhook endpoint.","sidebar":"tutorialSidebar"},"company-access":{"id":"company-access","title":"Company access control (join modes)","description":"Companies control how new OAuth users gain access after a successful provider login.","sidebar":"tutorialSidebar"},"configuration":{"id":"configuration","title":"Configuration","description":"Operators configure identity-service with environment variables (see .env.example in the repository root). Copy it to .env for local runs; pass the same keys to Docker, Coolify, or your orchestrator in production.","sidebar":"tutorialSidebar"},"index":{"id":"index","title":"identity-service documentation","description":"Welcome to Shellui identity-service \u2014 a Django backend that provides Shellui-compatible authentication under /api/v1/*.","sidebar":"tutorialSidebar"},"jwks":{"id":"jwks","title":"JWT signing and JWKS","description":"identity-service issues JWT access and refresh tokens for Shellui sessions and personal access tokens (PATs). External services can verify those tokens without sharing SECRET_KEY by fetching the public keys from the JWKS endpoint.","sidebar":"tutorialSidebar"},"magic-link":{"id":"magic-link","title":"Magic link (passwordless email) login","description":"Company-scoped magic link sign-in complements OAuth. Users request a one-time link by email; clicking the link (or calling the consume API) yields Shellui JWTs using the same session delivery options as OAuth (OAUTHTOKENDELIVERY).","sidebar":"tutorialSidebar"},"metrics":{"id":"metrics","title":"Accessing platform metrics","description":"The service exposes Prometheus-compatible metrics over HTTP:","sidebar":"tutorialSidebar"},"n8n":{"id":"n8n","title":"Using Shellui webhooks with n8n","description":"Shellui identity-service (and sibling hosting-service and storage-service) can POST signed JSON to an n8n Webhook node when domain events fire. This page shows a production-ready n8n setup, signature verification, and how retries behave when a workflow is inactive."},"oauth-login":{"id":"oauth-login","title":"Identity-hosted OAuth login","description":"For passwordless email (magic link) sign-in, see magic-link.md. OAuth and magic link can both be enabled per company.","sidebar":"tutorialSidebar"},"oauth-providers":{"id":"oauth-providers","title":"Social login providers (django-allauth)","description":"identity-service stores OAuth client credentials in django-allauth SocialApp rows (linked to companies via CompanyOAuthClient). The service depends on django-allauth 65.14.1 (pyproject.toml / uv.lock).","sidebar":"tutorialSidebar"},"RELEASES":{"id":"RELEASES","title":"Releases and Docker Hub","description":"Canonical guide: PUBLISH.md at the repository root.","sidebar":"tutorialSidebar"},"scim":{"id":"scim","title":"Enterprise SCIM (user and group provisioning)","description":"Shellui identity-service can act as a SCIM 2.0 service provider for per-company user and group provisioning. Each company has its own SCIM base URL and bearer token; provisioned users are normal Django users with company membership (CompanyMembership.is_enabled), and groups map to CompanyGroup (SCIM field names, same company scope).","sidebar":"tutorialSidebar"},"security-hardening":{"id":"security-hardening","title":"Security hardening (auth abuse & transport)","description":"Production deployments should configure the controls below. Defaults follow DEBUG=false unless noted.","sidebar":"tutorialSidebar"}}}}')}}]);